create or replace function finance_private.current_billing_batch_worker_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.current_actor_can_manage_billing_batch(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select false$$;
revoke all on function finance_private.current_billing_batch_worker_is_trusted() from public,anon,authenticated;
revoke all on function finance_private.current_actor_can_manage_billing_batch(uuid,uuid,uuid,uuid,text) from public,anon,authenticated;

create or replace function finance_api.authorize_billing_batch_scope(p_dealer_account_id uuid,p_branch_id uuid,p_batch_id uuid,p_permission text)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,finance,finance_private,auth as $$
declare v_legal uuid;v_account uuid;v_branch uuid;begin
 if p_permission not in('finance.billing-batches.create','finance.billing-batches.export') or auth.uid() is null then return pg_catalog.jsonb_build_object('allowed',false);end if;
 if p_batch_id is not null then select b.legal_entity_id,b.dealer_account_id,b.branch_id into v_legal,v_account,v_branch from finance.billing_batches b where b.id=p_batch_id;else select da.legal_entity_id,da.id,b.id into v_legal,v_account,v_branch from finance.dealer_accounts da join finance.branches b on b.dealer_legal_entity_id=da.dealer_legal_entity_id and b.legal_entity_id=da.legal_entity_id where da.id=p_dealer_account_id and b.id=p_branch_id and da.status in('SHADOW','ACTIVE') and b.status='ACTIVE';end if;
 if not found or not finance_private.current_actor_can_manage_billing_batch(auth.uid(),v_legal,v_account,v_branch,p_permission) then return pg_catalog.jsonb_build_object('allowed',false);end if;
 return pg_catalog.jsonb_build_object('allowed',true,'legalEntityId',v_legal,'dealerAccountId',v_account,'branchId',v_branch);
end $$;

revoke all on function finance_api.authorize_billing_batch_scope(uuid,uuid,uuid,text) from public,anon;
grant execute on function finance_api.authorize_billing_batch_scope(uuid,uuid,uuid,text) to authenticated;

create or replace function finance_api.commit_billing_batch_creation(
  p_actor_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_finance_period_id uuid,
  p_grouping_profile_code text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid
) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_api,finance_private as $$
declare p finance.finance_periods%rowtype;e finance.billing_batches%rowtype;v_id uuid:=gen_random_uuid();v_batch_no text;v_net numeric(24,8);v_tax numeric(24,8);v_gross numeric(24,8);v_count integer;v_content text;v_payload jsonb;v_audit text;v_previous text;
begin
 if not finance_private.current_billing_batch_worker_is_trusted() then raise exception using errcode='42501',message='billing batch worker denied';end if;
 if p_actor_id is null or p_legal_entity_id is null or p_dealer_account_id is null or p_branch_id is null or p_finance_period_id is null or pg_catalog.btrim(coalesce(p_grouping_profile_code,''))='' or pg_catalog.length(p_grouping_profile_code)>100 or pg_catalog.btrim(coalesce(p_idempotency_key,''))='' or pg_catalog.length(p_idempotency_key)>200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' or p_correlation_id is null then raise exception using errcode='22023',message='required billing batch fields missing';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('billing-batch:'||p_legal_entity_id::text||':'||p_dealer_account_id::text||':'||p_branch_id::text||':'||p_finance_period_id::text,0));
 select * into e from finance.billing_batches b where b.legal_entity_id=p_legal_entity_id and b.idempotency_key=p_idempotency_key for update;
 if found then if e.intent_hash=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','batchId',e.id,'financePeriodId',e.finance_period_id,'dealerAccountId',e.dealer_account_id,'branchId',e.branch_id,'currencyCode',e.currency_code,'status',e.status,'contentHash',e.content_hash,'controlTotals',pg_catalog.jsonb_build_object('netAmount',e.control_net::text,'taxAmount',e.control_tax::text,'grossAmount',e.control_gross::text,'currency',e.currency_code),'version',e.version);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select * into p from finance.finance_periods fp where fp.id=p_finance_period_id and fp.legal_entity_id=p_legal_entity_id and fp.scope_type='BRANCH' and fp.dealer_account_id=p_dealer_account_id and fp.branch_id=p_branch_id and fp.mode='LIVE' and fp.status='LOCKED' for update;
 if not found then raise exception using errcode='23514',message='locked branch finance period required';end if;
 perform 1 from finance.accruals a join finance.journal_entries je on je.id=a.journal_entry_id where a.legal_entity_id=p_legal_entity_id and a.dealer_account_id=p_dealer_account_id and a.branch_id=p_branch_id and a.currency_code=p.currency_code and a.status='POSTED' and a.reversal_of_id is null and a.gross_amount>0 and je.finance_period_id=p.id and je.status='POSTED' and not exists(select 1 from finance.billing_batch_items bi where bi.accrual_id=a.id and bi.status='ACTIVE') order by a.id for update of a;
 select pg_catalog.count(*),coalesce(pg_catalog.sum(a.net_amount),0),coalesce(pg_catalog.sum(a.tax_amount),0),coalesce(pg_catalog.sum(a.gross_amount),0),pg_catalog.encode(extensions.digest(pg_catalog.convert_to(pg_catalog.string_agg(a.id::text||':'||a.net_amount::text||':'||a.tax_amount::text||':'||a.gross_amount::text,'|' order by a.id),'UTF8'),'sha256'),'hex') into v_count,v_net,v_tax,v_gross,v_content from finance.accruals a join finance.journal_entries je on je.id=a.journal_entry_id where a.legal_entity_id=p_legal_entity_id and a.dealer_account_id=p_dealer_account_id and a.branch_id=p_branch_id and a.currency_code=p.currency_code and a.status='POSTED' and a.reversal_of_id is null and a.gross_amount>0 and je.finance_period_id=p.id and je.status='POSTED' and not exists(select 1 from finance.billing_batch_items bi where bi.accrual_id=a.id and bi.status='ACTIVE');
 if v_count=0 or v_gross<>v_net+v_tax then raise exception using errcode='23514',message='eligible unbilled accruals required';end if;
 v_batch_no:='BILL-'||pg_catalog.upper(pg_catalog.substr(pg_catalog.replace(v_id::text,'-',''),1,16));
 insert into finance.billing_batches(id,legal_entity_id,finance_period_id,dealer_account_id,branch_id,idempotency_key,intent_hash,batch_no,grouping_profile_code,currency_code,control_net,control_tax,control_gross,content_hash,status,created_by,correlation_id) values(v_id,p_legal_entity_id,p.id,p_dealer_account_id,p_branch_id,p_idempotency_key,p_intent_hash,v_batch_no,p_grouping_profile_code,p.currency_code,v_net,v_tax,v_gross,v_content,'READY',p_actor_id,p_correlation_id);
 insert into finance.billing_batch_items(billing_batch_id,accrual_id,net_amount,tax_amount,gross_amount,status,created_by,correlation_id) select v_id,a.id,a.net_amount,a.tax_amount,a.gross_amount,'ACTIVE',p_actor_id,p_correlation_id from finance.accruals a join finance.journal_entries je on je.id=a.journal_entry_id where a.legal_entity_id=p_legal_entity_id and a.dealer_account_id=p_dealer_account_id and a.branch_id=p_branch_id and a.currency_code=p.currency_code and a.status='POSTED' and a.reversal_of_id is null and a.gross_amount>0 and je.finance_period_id=p.id and je.status='POSTED' and not exists(select 1 from finance.billing_batch_items bi where bi.accrual_id=a.id and bi.status='ACTIVE') order by a.id;
 if (select pg_catalog.count(*) from finance.billing_batch_items bi where bi.billing_batch_id=v_id and bi.status='ACTIVE')<>v_count then raise exception using errcode='23514',message='billing batch item coverage mismatch';end if;
 v_payload:=pg_catalog.jsonb_build_object('batchId',v_id,'financePeriodId',p.id,'dealerAccountId',p_dealer_account_id,'branchId',p_branch_id,'currencyCode',p.currency_code,'status','READY','contentHash',v_content,'itemCount',v_count);
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.billing','BILLING_BATCH_READY','billing_batch',v_id,1,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select ae.integrity_hash into v_previous from finance.audit_events ae where ae.legal_entity_id=p_legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||v_id::text||':BILLING_BATCH_READY:'||v_content||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','BILLING_BATCH_READY','billing_batch',v_id,'ALLOW',v_content,v_previous,v_audit,pg_catalog.jsonb_build_object('dealerAccountId',p_dealer_account_id,'branchId',p_branch_id,'itemCount',v_count),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','CREATED','batchId',v_id,'financePeriodId',p.id,'dealerAccountId',p_dealer_account_id,'branchId',p_branch_id,'currencyCode',p.currency_code,'status','READY','contentHash',v_content,'controlTotals',pg_catalog.jsonb_build_object('netAmount',v_net::text,'taxAmount',v_tax::text,'grossAmount',v_gross::text,'currency',p.currency_code),'version',1);
end $$;

create or replace function finance_api.commit_billing_batch_export(
 p_actor_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_batch_id uuid,p_target_adapter_code text,p_mapping_version text,p_expected_version bigint,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid
) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_api,finance_private as $$
declare b finance.billing_batches%rowtype;v_job uuid:=gen_random_uuid();v_new bigint;v_payload jsonb;v_previous text;v_audit text;
begin
 if not finance_private.current_billing_batch_worker_is_trusted() then raise exception using errcode='42501',message='billing batch worker denied';end if;
 if p_actor_id is null or p_expected_version<1 or pg_catalog.btrim(coalesce(p_target_adapter_code,''))='' or pg_catalog.btrim(coalesce(p_mapping_version,''))='' or pg_catalog.btrim(coalesce(p_idempotency_key,''))='' or p_intent_hash!~'^[a-fA-F0-9]{64}$' or p_correlation_id is null then raise exception using errcode='22023',message='required billing export fields missing';end if;
 select * into b from finance.billing_batches where id=p_batch_id and legal_entity_id=p_legal_entity_id and dealer_account_id=p_dealer_account_id and branch_id=p_branch_id for update;if not found then raise exception using errcode='P0002',message='billing batch not found';end if;
 if b.export_idempotency_key is not null then if b.export_idempotency_key=p_idempotency_key and b.export_intent_hash=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','jobId',b.export_job_id,'status','QUEUED','correlationId',p_correlation_id);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if b.status<>'READY' or b.version<>p_expected_version then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 update finance.billing_batches set export_idempotency_key=p_idempotency_key,export_intent_hash=p_intent_hash,target_adapter_code=p_target_adapter_code,mapping_version=p_mapping_version,export_job_id=v_job,export_queued_at_utc=pg_catalog.statement_timestamp(),export_queued_by=p_actor_id,status='EXPORT_QUEUED',version=version+1,correlation_id=p_correlation_id where id=b.id and version=p_expected_version returning version into v_new;if not found then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 v_payload:=pg_catalog.jsonb_build_object('jobId',v_job,'batchId',b.id,'contentHash',b.content_hash,'targetAdapterCode',p_target_adapter_code,'mappingVersion',p_mapping_version,'dealerAccountId',b.dealer_account_id,'branchId',b.branch_id);
 insert into finance.outbox_messages(id,legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(v_job,p_legal_entity_id,'finance.billing.export','BILLING_BATCH_EXPORT_QUEUED','billing_batch',b.id,v_new,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select ae.integrity_hash into v_previous from finance.audit_events ae where ae.legal_entity_id=p_legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||b.id::text||':BILLING_BATCH_EXPORT_QUEUED:'||p_intent_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','BILLING_BATCH_EXPORT_QUEUED','billing_batch',b.id,'ALLOW',b.content_hash,p_intent_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('jobId',v_job,'adapter',p_target_adapter_code,'mappingVersion',p_mapping_version),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','QUEUED','jobId',v_job,'status','QUEUED','correlationId',p_correlation_id);
end $$;

revoke all on function finance_api.commit_billing_batch_creation(uuid,uuid,uuid,uuid,uuid,text,text,text,uuid) from public,anon,authenticated;
revoke all on function finance_api.commit_billing_batch_export(uuid,uuid,uuid,uuid,uuid,text,text,bigint,text,text,uuid) from public,anon,authenticated;
